INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(3101, 'Leviticus 16:13', 'Leviticus', 16, 13, '&nbsp;هغه به هلته د مالِک خُدائ په حضور کښې خوشبوئى په اور باندې واچوى او د خوشبويۍ لوګے به د لوظ صندوق د کفارې تخت پټ کړى نو هغه به دا ونۀ ګورى او مړ به نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3102, 'Leviticus 16:14', 'Leviticus', 16, 14, '&nbsp;هغه به د غوَيى لږه وينه واخلى او د خپلې ګوتې سره به يې د صندوق د کفارې تخت نمرخاتۀ طرف ته وشيندى او بيا به لږه د لوظ صندوق د کفارې تخت په مخکښې اووۀ ځله وشيندى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3103, 'Leviticus 16:15', 'Leviticus', 16, 15, '&nbsp;د هغې نه پس، هغه به چېلے د خلقو دپاره د ګناه د نذرانې په توګه حلال کړى، وينه به يې زيات مقدس ځائ ته راوړى، د صندوق د کفارې په تخت او په مخکښې به يې وشيندى، هم هغه شان چې څنګه يې د غوَيى د وينې سره کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3104, 'Leviticus 16:16', 'Leviticus', 16, 16, '&nbsp;نو په دې کولو سره به هغه د زيات مقدس ځائ د پاکوالى کفاره ادا کړى چې د بنى اِسرائيلو د ناپاکۍ او د ټولو ګناهونو نه پاک شى. هغه به د مقدسې خېمې دپاره خامخا داسې وکړى، ځکه چې هغه د کېمپ په مينځ کښې ولاړه ده، کوم ځائ چې ناپاک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3105, 'Leviticus 16:17', 'Leviticus', 16, 17, '&nbsp;د هارون د پاکوالى کفاره ادا کولو دپاره زيات مقدس ځائ ته ننوتلو نه واخله د هغۀ د بهر راوتلو پورې، هلته به په خېمه کښې هيڅ څوک نۀ وى. چې په کوم وخت هغه د ځان، د خپل خاندان او د ټول قوم دپاره کفاره ادا کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3106, 'Leviticus 16:18', 'Leviticus', 16, 18, '&nbsp;بيا به هغه خامخا د سوزېدونکې نذرانو دپاره بهر قربان‌ګاه ته لاړ شى او پاکه به يې کړى. هغه به لږه د غوَيى وينه او لږه د چېلى وينه واخلى او د قربان‌ګاه په ټولو ښکرونو پورې دې ولګوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3107, 'Leviticus 16:19', 'Leviticus', 16, 19, '&nbsp;هغه دې د خپلې ګوتې سره لږه وينه اووۀ ځله په قربان‌ګاه باندې وشيندى. نو دا به د بنى اِسرائيلو د ګناهونو نه پاکه کړى او مقدسه به يې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3108, 'Leviticus 16:20', 'Leviticus', 16, 20, '&nbsp;چې کله هارون د زيات مقدس ځائ، د مالِک خُدائ د حضور د ټولې مقدسې خېمې او د قربان‌ګاه د پاکوالى کفاره ادا کول ختم کړى، نو هغه به مالِک خُدائ ته هغه ژوندے چېلے پېش کړى چې د عزازيل دپاره خوښ شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3109, 'Leviticus 16:21', 'Leviticus', 16, 21, '&nbsp;خپل دواړه لاسونه به د چېلى په سر کېږدى او د ټولو بدو عملونو، ګناهونو او بنى اِسرائيلو د سرکشو اِقرار به وکړى او دا به د چېلى په سر واچوى. بيا به يو مقرر شوے سړے دا چېلے بيابان ته بوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3110, 'Leviticus 16:22', 'Leviticus', 16, 22, '&nbsp;چېلے به د ځان سره د هغوئ ټول ګناهونه په بيابان کښې يوې غېر‌ابادې علاقې ته يوسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3111, 'Leviticus 16:23', 'Leviticus', 16, 23, '&nbsp;نو بيا به هارون مقدسې خېمې ته ننوځى، زيات مقدس ځائ ته د ننوتلو نه مخکښې هغۀ چې کوم د اِمامانو د کتان لِباس اغوستے وو نو هغه به وباسى او هلته به يې پرېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3112, 'Leviticus 16:24', 'Leviticus', 16, 24, '&nbsp;هغه به په يو مقدس ځائ کښې غسل وکړى او خپلې جامې به واغوندى. د هغې نه پس، هغه به بهر لاړ شى او د خپلو ګناهونو او د خلقو ګناهونو لرې کولو کفارې دپاره به سوزېدونکې نذرانه پېش کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3113, 'Leviticus 16:25', 'Leviticus', 16, 25, '&nbsp;د ځناور وازګه به په قربان‌ګاه باندې وسوزوى چې د ګناه د نذرانې دپاره ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3114, 'Leviticus 16:26', 'Leviticus', 16, 26, '&nbsp;کوم سړى چې دا چېلے په بيابان کښې عزازيل له بوتلے وى نو کېمپ ته واپس راتلو نه مخکښې هغه به خپلې جامې ووينځى او غسل به وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3115, 'Leviticus 16:27', 'Leviticus', 16, 27, '&nbsp;کوم غوَيے او چېلے چې د ګناه د نذرانې دپاره استعمال شوى وُو چې وينه يې د ګناه د کفارې ادا کولو دپاره زيات مقدس ځائ ته راوړلے شوې وه، دا به د کېمپ نه بهر وړلے شى او سوزولے به شى. څرمن، غوښه او کولمې هر څۀ به سوزولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3116, 'Leviticus 16:28', 'Leviticus', 16, 28, '&nbsp;څوک چې دا وسوزوى نو کېمپ ته واپس راتلو نه مخکښې هغه به خپلې جامې ووينځى او غسل به وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3117, 'Leviticus 16:29', 'Leviticus', 16, 29, '&nbsp;دا اصُول به د همېشه دپاره وى. د اوومې مياشتې په لسمه ورځ اِسرائيليان او د هغوئ سره مهاجر خلق به خامخا روژه نيسى او هيڅ کار به نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3118, 'Leviticus 16:30', 'Leviticus', 16, 30, '&nbsp;په هغه ورځ به د هغوئ د ټولو ګناهونو نه د پاکوالى کفاره ادا شى او هغوئ به پاک شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3119, 'Leviticus 16:31', 'Leviticus', 16, 31, '&nbsp;چې په کومه ورځ باندې هغوئ روژه نيسى او کار نۀ کوى نو هغه به يوه ډېره مقدسه ورځ وى. دا اصُول به د همېشه دپاره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3120, 'Leviticus 16:32', 'Leviticus', 16, 32, '&nbsp;کوم مشر اِمام چې د پلار په ځائ مقرر شوے وى، هغه به د پاکوالى کفاره ادا کړى. هغه به د اِمامانو د کتان لِباس واغوندى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3121, 'Leviticus 16:33', 'Leviticus', 16, 33, '&nbsp;او د زيات مقدس ځائ، د مالِک خُدائ د حضور ټولې مقدسې خېمې، قربان‌ګاه، د اِمامانو او د ټول قوم د پاکوالى کفاره به ادا کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3122, 'Leviticus 16:34', 'Leviticus', 16, 34, '&nbsp;دا اصُول به د همېشه دپاره وى. په کال کښې يو ځل به خامخا د اِسرائيلو د ټولې ګناه نه د پاکوالى دپاره کفاره ادا کيږى. نو موسىٰ هم هغه شان وکړل چې څنګه مالِک خُدائ حُکم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3123, 'Leviticus 17:1', 'Leviticus', 17, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته حُکم وکړو چې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3124, 'Leviticus 17:2', 'Leviticus', 17, 2, '&nbsp;هارون د هغۀ زامنو او ټولو اِسرائيلو ته دا اصُول وښائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3125, 'Leviticus 17:5', 'Leviticus', 17, 5, '&nbsp;د دې حُکم مطلب دا دے چې اِسرائيلو کوم ځناور په کولاو مېدان کښې حلالول نو هغوئ به هغه مالِک خُدائ ته راولى. هغوئ به دا د مقدسې خېمې د دروازې په خولۀ کښې اِمام له راولى او د سلامتۍ د نذرانو په توګه به يې حلالوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3126, 'Leviticus 17:6', 'Leviticus', 17, 6, '&nbsp;اِمام به هغه وينه د مقدسې خېمې د دروازې په خولۀ کښې د قربان‌ګاه په طرفونو باندې وشيندى او د خوشبوئى جوړېدو دپاره دې وازګه وسوزوى، په مالِک خُدائ باندې دا خوشبو ښۀ لګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3127, 'Leviticus 17:7', 'Leviticus', 17, 7, '&nbsp;اِسرائيليان دې د مالِک خُدائ سره نوره بې‌وفائى نۀ کوى چې خپل ځناور د چېلو په شان ښکارېدونکو پيريانو ته قربانى کړى. اِسرائيل به په راتلونکى ټولو وختونو کښې دا اصُول خامخا منى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3128, 'Leviticus 17:8', 'Leviticus', 17, 8, '&nbsp;يو اِسرائيلے يا د پردى مُلک هر يو کس چې د هغوئ سره اوسيږى چې هغه يوه سوزېدونکې نذرانه يا بله څۀ قربانى پېش کوى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3129, 'Leviticus 17:9', 'Leviticus', 17, 9, '&nbsp;او د مقدسې خېمې د دروازې خولې ته يې مالِک خُدائ ته د پېش کولو دپاره رانۀ وړى نو هغه کس به نور د خُدائ پاک د خلقو نه نۀ شى ګڼلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3130, 'Leviticus 17:10', 'Leviticus', 17, 10, '&nbsp;هر يو اِسرائيلے يا د بل مُلک کس چې د هغوئ سره اوسيږى کۀ هغه غوښه خورى چې وينه لا په کښې وى، نو مالِک خُدائ به د هغۀ خِلاف شى او هغه به نور د هغۀ د خلقو نه نۀ شى ګڼلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3131, 'Leviticus 17:11', 'Leviticus', 17, 11, '&nbsp;د هر ژوندى څيز ژوند په وينه کښې دے او دا ځکه مالِک خُدائ حُکم کړے دے چې ټوله وينه به په قربان‌ګاه توئ کړے شى چې د خلقو د ګناه کفاره ادا شى، دا وينه ده چې د ګناهونو کفاره ادا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3132, 'Leviticus 17:12', 'Leviticus', 17, 12, '&nbsp;دا ځکه مالِک خُدائ بنى اِسرائيلو ته فرمائيلى دى چې نۀ به هغوئ او نۀ به د هغوئ سره مهاجر هغه غوښه خورى چې وينه لا په کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3133, 'Leviticus 17:13', 'Leviticus', 17, 13, '&nbsp;هر يو اِسرائيلے يا د پردى مُلک کس چې د هغوئ سره اوسيږى کۀ د يو ځناور يا مارغۀ ښکار وکړى کوم چې حلال وى، نو هغه به خامخا د دې وينه په زمکه توئ کړى او په خاوره به يې پټه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3134, 'Leviticus 17:14', 'Leviticus', 17, 14, '&nbsp;د هر ژوندى څيز ژوند په وينه کښې دے، نو دا ځکه مالِک خُدائ اِسرائيلو ته فرمائيلى دى چې هغوئ به هغه غوښه نۀ خورى چې وينه لا په کښې وى خو کۀ چا وخوړله نو هغه به نور د هغۀ د خلقو نه نۀ شى ګڼلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3135, 'Leviticus 17:15', 'Leviticus', 17, 15, '&nbsp;هر څوک، کۀ هغه اِسرائيلے وى يا د پردى مُلک کس، کۀ هغۀ د يو داسې ځناور غوښه وخوړله چې هغه په خپل مرګ مړ وى يا ځنګلى ځناورو وژلے وى نو هغه به خامخا خپلې جامې ووينځى، غسل به وکړى او تر ماښامه پورې به هغه ناپاک وى خو بيا به پاک شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3136, 'Leviticus 17:16', 'Leviticus', 17, 16, '&nbsp;کۀ هغۀ داسې ونۀ کړل، نو هغۀ ته به د خپلو بدو سزا مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3137, 'Leviticus 18:1', 'Leviticus', 18, 1, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3138, 'Leviticus 18:2', 'Leviticus', 18, 2, '&nbsp;”بنى اِسرائيلو ته ووايه چې، زۀ مالِک خُدائ ستاسو خُدائ پاک يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3139, 'Leviticus 18:3', 'Leviticus', 18, 3, '&nbsp;تاسو هغه شان کارونه مۀ کوئ څنګه چې د مِصر د مُلک خلقو کول، چرته چې تاسو اوسېدلئ او تاسو هغه شان کار هم مۀ کوئ څنګه چې د کنعان خلق يې کوى، چرته چې زۀ تاسو بوځم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3140, 'Leviticus 18:4', 'Leviticus', 18, 4, '&nbsp;تاسو به زما حُکمونه منئ او زما په قانون به عمل کوئ. زۀ مالِک خُدائ ستاسو خُدائ پاک يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3141, 'Leviticus 18:5', 'Leviticus', 18, 5, '&nbsp;تاسو زما په شريعت او حُکمونو عمل کوئ، هر څوک چې پرې عمل کوى نو هغوئ به د دې په سبب پائى. زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3142, 'Leviticus 18:6', 'Leviticus', 18, 6, '&nbsp;هيڅ څوک دې د خپلوانو سره زنا نۀ کوى. زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3143, 'Leviticus 18:7', 'Leviticus', 18, 7, '&nbsp;د خپلې مور سره زنا کولو په وجه د خپل پلار سپکاوے مۀ کوئ، هغه ستاسو مور ده. د خپلې مور سره به هيڅکله داسې غلط کار نۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3144, 'Leviticus 18:8', 'Leviticus', 18, 8, '&nbsp;د خپل پلار د نورو ښځو سره زنا مۀ کوئ، دا ستاسو د پلار سپکاوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3145, 'Leviticus 18:9', 'Leviticus', 18, 9, '&nbsp;د خپلې سکه يا ناسکه خور سره زنا مۀ کوئ، کۀ هغه ستاسو په کور کښې لويه شوې وى يا په بل ځائ کښې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
