(3147, 'Leviticus 18:11', 'Leviticus', 18, 11, '&nbsp;د خپلې ناسکه خور سره زنا مۀ کوئ، ځکه چې هغه ستاسو خور ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3148, 'Leviticus 18:14', 'Leviticus', 18, 14, '&nbsp;د خپل ترۀ د ښځې سره د زنا کولو په وجه د هغۀ سپکاوے مۀ کوئ، ځکه چې هغه ستاسو د ترۀ ښځه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3149, 'Leviticus 18:15', 'Leviticus', 18, 15, '&nbsp;د خپلې اِنږور سره زنا مۀ کوئ، هغه ستاسو د زوئ ښځه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3150, 'Leviticus 18:16', 'Leviticus', 18, 16, '&nbsp;د خپلې ورندارې سره زنا مۀ کوئ، دا ستاسو د خپل ورور سپکاوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3151, 'Leviticus 18:17', 'Leviticus', 18, 17, '&nbsp;چې تاسو د يوې ښځې سره څملئ نو د هغې د لور يا د هغې د نمسۍ سره هم زنا مۀ کوئ، ځکه چې هغوئ ستاسو خپلوانې دى، دا به يو بد عمل وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3152, 'Leviticus 18:18', 'Leviticus', 18, 18, '&nbsp;د خپلې ښينې سره وادۀ مۀ کوئ چې کله د هغې خور يعنې ستاسو ښځه ژوندۍ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3153, 'Leviticus 18:19', 'Leviticus', 18, 19, '&nbsp;چې کله د يوې ښځې مياشتنۍ بيمارى وى نو د هغې سره مۀ څملئ ځکه چې هغه ناپاکه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3154, 'Leviticus 18:20', 'Leviticus', 18, 20, '&nbsp;د بل سړى د ښځې سره مۀ څملئ، د هغې په وجه به تاسو ناپاک شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3155, 'Leviticus 18:21', 'Leviticus', 18, 21, '&nbsp;د خپل اولاد يو کس هم د مولک بُت دپاره مۀ ورکوئ چې د هغۀ په عبادت کښې استعمال شى ځکه چې په داسې کولو سره د خپل خُدائ پاک د نوم سپکاوے کوئ. زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3156, 'Leviticus 18:22', 'Leviticus', 18, 22, '&nbsp;يو نر دې هم د بل نر کس سره جنسى تعلقات نۀ ساتى، دا يو بد عمل دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3157, 'Leviticus 18:23', 'Leviticus', 18, 23, '&nbsp;يو نر دې د يو ځناور سره زنا کولو په وجه خپل ځان نۀ ناپاک کوى، يا يوه ښځه دې د يو ځناور سره د زنا کولو کوشش نۀ کوى، دا يو ګنده عمل دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3158, 'Leviticus 18:24', 'Leviticus', 18, 24, '&nbsp;د دې عملونو په وجه خپل ځانونه مۀ ناپاکه کوئ، ځکه چې غېرو قومونو داسې خپل ځانونه ناپاک کړل، هغه غېرقومونه چې مالِک خُدائ به يې ستاسو نه مخکښې وشړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3159, 'Leviticus 18:25', 'Leviticus', 18, 25, '&nbsp;د هغوئ عملونو هغه مُلک ناپاک کړو او مالِک خُدائ هغه مُلک له سزا ورکړه چې خپل اوسېدونکى وشړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3160, 'Leviticus 18:28', 'Leviticus', 18, 28, '&nbsp;نو هغه مُلک به تاسو نۀ شړى، لکه چې څنګه يې غېرقومونه وشړل کوم چې ستاسو نه مخکښې هلته اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3161, 'Leviticus 18:29', 'Leviticus', 18, 29, '&nbsp;تاسو ته پته ده چې هر څوک دا حرام کارونه وکړى نو هغه به نور د خُدائ پاک د خلقو نه نۀ شى ګڼلے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3162, 'Leviticus 18:30', 'Leviticus', 18, 30, '&nbsp;او مالِک خُدائ وفرمائيل، ”زۀ چې کوم حُکمونه درکړم په هغې عمل کوئ او د هغه خلقو په رِواجونو پسې مۀ ځئ کوم چې ستاسو نه مخکښې په هغه مُلک کښې اوسېدل، او د هغه غلطو کارونو کولو په وجه خپل ځانونه مۀ ناپاکه کوئ. زۀ مالِک خُدائ ستاسو خُدائ پاک يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3163, 'Leviticus 19:1', 'Leviticus', 19, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3164, 'Leviticus 19:2', 'Leviticus', 19, 2, '&nbsp;”د اِسرائيلو قوم ته ووايه، مقدس اوسئ، ځکه چې زۀ مالِک خُدائ، ستاسو خُدائ پاک مقدس يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3165, 'Leviticus 19:3', 'Leviticus', 19, 3, '&nbsp;ستاسو هر يو کس دې د خپل مور او پلار عزت کوى او د سبت ورځ مانځئ، چې څنګه ما حُکم درکړے دے. زۀ مالِک خُدائ ستاسو خُدائ پاک يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3166, 'Leviticus 19:4', 'Leviticus', 19, 4, '&nbsp;زما نه مۀ اوړئ او د بُتانو عبادت مۀ کوئ، مجسمې مۀ جوړَوئ او مۀ يې عبادت کوئ. زۀ مالِک خُدائ ستاسو خُدائ پاک يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3167, 'Leviticus 19:5', 'Leviticus', 19, 5, '&nbsp;کله چې تاسو د سلامتۍ نذرانې دپاره يو ځناور حلالوئ، ما چې کوم اصُول درته ښودلى دى د هغې خيال ساتئ او زۀ به هغه نذرانه قبلوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3168, 'Leviticus 19:6', 'Leviticus', 19, 6, '&nbsp;چې په کومه ورځ ځناور حلال شى غوښه به يې هم په هغه ورځ يا ورپسې ورځ باندې خوړلے شى. څۀ غوښه چې د درېمې ورځې پورې پاتې وى نو هغه به خامخا سوزولے شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3169, 'Leviticus 19:7', 'Leviticus', 19, 7, '&nbsp;ځکه چې دا ناپاکه ده او کۀ څوک دا وخورى، نو زۀ به هغه نذرانه قبوله نۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3170, 'Leviticus 19:8', 'Leviticus', 19, 8, '&nbsp;هر څوک چې دا وخورى نو ګناه به د هغۀ په غاړه وى ځکه چې د هغه څۀ سپکاوے يې کړے دے چې مالِک خُدائ، ته وقف وُو، نو هغه به نور زما د خلقو نۀ شى ګڼلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3171, 'Leviticus 19:9', 'Leviticus', 19, 9, '&nbsp;کله چې تاسو د خپلو پټو فصل رېبئ، نو فصل د پټو تر غاړو پورې مۀ رېبئ او چې کوم وَږى د لَو نه پاتې وى نو د هغې رېبلو له واپس مۀ ورځئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3172, 'Leviticus 19:10', 'Leviticus', 19, 10, '&nbsp;خپلو د انګورو باغونو ته واپس مۀ ورځئ چې هغه انګور راټول کړئ کوم چې پاتې شوى وى يا غورزېدلى وى، دا غريبانانو او مسافرو ته پرېږدئ. زۀ مالِک خُدائ ستاسو خُدائ پاک يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3173, 'Leviticus 19:11', 'Leviticus', 19, 11, '&nbsp;غلا مۀ کوئ، دروغ مۀ وايئ او يو بل مۀ دوکه کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3174, 'Leviticus 19:12', 'Leviticus', 19, 12, '&nbsp;زما په نوم د دروغو قسم مۀ خورئ چې ستاسو د دې د پوره کولو اراده نۀ وى، دا به زما د نوم سپکاوے وى. زۀ مالِک خُدائ ستاسو خُدائ پاک يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3175, 'Leviticus 19:13', 'Leviticus', 19, 13, '&nbsp;خپل ګاونډى مۀ دوکه کوئ او د هغۀ نه غلا مۀ کوئ. د يو مزدور مزدورى تر سحره پورې مۀ ايساروئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3176, 'Leviticus 19:14', 'Leviticus', 19, 14, '&nbsp;يو کُوڼ کس ته ښېرې مۀ کوئ او د يو ړوند په مخکښې داسې څۀ څيز مۀ ږدئ چې په هغې باندې تيندک وخورى. زما نه يرېږئ، زۀ مالِک خُدائ ستاسو خُدائ پاک يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3177, 'Leviticus 19:15', 'Leviticus', 19, 15, '&nbsp;د عدالت په فېصلو کښې د بې‌اِنصافۍ نه کار مۀ اخلئ، چې د يو غريب طرفدارى وکړئ يا د مالدار کس نه يرېږئ، د خپل ګاونډى سره اِنصاف کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3178, 'Leviticus 19:16', 'Leviticus', 19, 16, '&nbsp;د هيچا په حقله دروغ مۀ خوروئ او کله چې د چا د ژوند مقدمه وى، کۀ هغه ستاسو د ګواهۍ په وجه بچ کېدے شى نو ګواهى ورکړئ. زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3179, 'Leviticus 19:17', 'Leviticus', 19, 17, '&nbsp;د نورو خِلاف په زړۀ کښې کينه مۀ ساتئ، د هغوئ سره خپل اختلافات ختم کړئ، نو چې د هغوئ په وجه ګناهګار نۀ شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3180, 'Leviticus 19:18', 'Leviticus', 19, 18, '&nbsp;د هيچا نه بدل مۀ اخلئ يا د چا سره په زړۀ کښې کينه مۀ ساتئ، د خپل ګاونډى سره د خپل ځان په شان مينه ساتئ. زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3181, 'Leviticus 19:19', 'Leviticus', 19, 19, '&nbsp;زما په حُکمونو عمل کوئ. مختلف قِسمه ځناور مۀ پرېږدئ چې يو بل مال کړى. په يو پټى کښې دوه قِسمه تخم مۀ کَرئ. د دوه قِسمه تار نه جوړې شوې جامې مۀ اغوندئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3182, 'Leviticus 19:20', 'Leviticus', 19, 20, '&nbsp;کۀ يوه وينځه د يو سړى منلے شوى دوېمه ښځه وى خو چې لا اخستے شوې نۀ وى چې آزاده شى، نو کۀ يو بل سړے د هغې سره څملى، هغوئ له به سزا ورکولے شى خو وژلے به نۀ شى، ځکه چې هغه يوه وينځه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3183, 'Leviticus 19:21', 'Leviticus', 19, 21, '&nbsp;هغه سړے به د مالِک خُدائ د مقدسې خېمې د دروازې خولې ته د ګناه د تاوان د نذرانې په توګه يو ګډ راولى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3184, 'Leviticus 19:22', 'Leviticus', 19, 22, '&nbsp;او اِمام به د دې سره د پاکوالى کفاره ادا کړى چې د هغه سړى ګناه لرې شى او خُدائ پاک به هغه معاف کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3185, 'Leviticus 19:23', 'Leviticus', 19, 23, '&nbsp;کله چې تاسو د کنعان مُلک ته ورننوځئ او د مېوې هر قِسم ونه هم وکَرئ، نو داسې وګڼئ چې هغه مېوه د درېو کالو پورې ناپاکه ده. په دې دوران کښې به تاسو هغه نۀ خورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3186, 'Leviticus 19:24', 'Leviticus', 19, 24, '&nbsp;په څلورم کال به ټولې مېوې ما يعنې مالِک خُدائ ته په شکرانه کښې وقف کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3187, 'Leviticus 19:25', 'Leviticus', 19, 25, '&nbsp;خو په پينځم کال هغه مېوې خوړے شئ. کۀ تاسو دا هر څۀ وکړل، نو ستاسو ونې به زياتې مېوې ونيسى. زۀ مالِک خُدائ ستاسو خُدائ پاک يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3188, 'Leviticus 19:26', 'Leviticus', 19, 26, '&nbsp;داسې غوښه مۀ خورئ چې وينه لا په کښې وى. فال مۀ ګورئ او کوډې مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3189, 'Leviticus 19:27', 'Leviticus', 19, 27, '&nbsp;د خپل سر ګېرچاپېره لاندې وېښتۀ مۀ کلوئ او ږيره مۀ لنډوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3190, 'Leviticus 19:28', 'Leviticus', 19, 28, '&nbsp;د مړى په غم کښې خپل بدن مۀ غوڅوئ او مۀ په کښې داغونه جوړَوئ. زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3191, 'Leviticus 19:29', 'Leviticus', 19, 29, '&nbsp;د خپلو لوڼو نه کنجرې مۀ جوړوى او په دې کار کولو سره د د هغوئ بې‌عزتى مۀ کوئ، ګنې نورو معبودانو ته به ور واوړى او هغه مُلک به د بدعملۍ نه ډک شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3192, 'Leviticus 19:30', 'Leviticus', 19, 30, '&nbsp;د سبت ورځ مانځئ او د هغه ځائ عزت کوئ چې چرته زما عبادت کيږى. زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3193, 'Leviticus 19:31', 'Leviticus', 19, 31, '&nbsp;د هغه خلقو نصيحت اورېدلو له مۀ ورځئ چې د مړو د روحونو مشورې ورکوى. کۀ تاسو داسې وکړل نو ناپاک به شئ. زۀ مالِک خُدائ ستاسو خُدائ پاک يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3194, 'Leviticus 19:32', 'Leviticus', 19, 32, '&nbsp;د بوډاګانو په مخکښې پاڅېږئ او د مشرانو عزت کوئ. زما نه يرېږئ، زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3195, 'Leviticus 19:33', 'Leviticus', 19, 33, '&nbsp;د هغه مسافرو سره بد سلوک مۀ کوئ کوم چې ستاسو په مُلک کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3196, 'Leviticus 19:34', 'Leviticus', 19, 34, '&nbsp;د هغوئ سره د يو اِسرائيلى په شان سلوک کوئ او د هغوئ سره د خپل ځان په شان مينه ساتئ. ياد ساتئ، تاسو هم په يو وخت کښې د مِصر په مُلک کښې مسافر وئ. زۀ مالِک خُدائ ستاسو خُدائ پاک يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3197, 'Leviticus 19:35', 'Leviticus', 19, 35, '&nbsp;د ناپ، تول، يا د مِقدار د غلطو حسابونو لګولو په وجه هيڅ څوک مۀ غولوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3198, 'Leviticus 19:36', 'Leviticus', 19, 36, '&nbsp;صحيح تلې، صحيح وزنونه او صحيح ناپونه استعمالوئ. زۀ مالِک خُدائ ستاسو خُدائ پاک يم او ما تاسو د مِصر مُلک نه راوويستلئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3199, 'Leviticus 19:37', 'Leviticus', 19, 37, '&nbsp;زما ټول قانون او حُکمونه منئ. زۀ مالِک خُدائ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3200, 'Leviticus 20:1', 'Leviticus', 20, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');